import{_ as s,o as t,c as a,a3 as n}from"./chunks/framework.B02wg2PO.js";const k=JSON.parse('{"title":"Scheduled Runs & Crons","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/scheduled-runs.md","filePath":"concepts/scheduled-runs.md"}'),i={name:"concepts/scheduled-runs.md"};function r(o,e,d,h,l,c){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="scheduled-runs-crons" tabindex="-1">Scheduled Runs &amp; Crons <a class="header-anchor" href="#scheduled-runs-crons" aria-label="Permalink to &quot;Scheduled Runs &amp; Crons&quot;">​</a></h1><p>A <strong>cron</strong> is a small durable record that says: at this schedule, start a Run with this brief. That is the whole of it. A cron owns no execution machinery — firing calls the run engine&#39;s <code>startRun()</code>, so a scheduled task gets everything a <a href="/docs/concepts/runs">Run</a> already has: PRIME orchestration, a shared context, approval gates, notifications, and a thread you can open and steer.</p><p>The trade this makes is deliberate. There is no queue, no worker pool, and no separate scheduled-job runtime to reason about. There is a clock, and there are runs.</p><h2 id="the-cron-record" tabindex="-1">The cron record <a class="header-anchor" href="#the-cron-record" aria-label="Permalink to &quot;The cron record&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CronJob</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  orgId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  createdBy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  schedule</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  brief</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  project</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  enabled</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  createdAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  updatedAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  nextFireAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  lastFiredAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  lastRunId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  lastSkippedAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  lastSkipReason</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th></tr></thead><tbody><tr><td><code>id</code></td><td>Generated at creation; also the Mongo <code>_id</code></td></tr><tr><td><code>orgId</code></td><td>Owning org in cloud mode. Absent on local records, which resolve to <code>local</code></td></tr><tr><td><code>createdBy</code></td><td>Fires act <strong>as</strong> this user — their budget, effort ceiling, and agent access govern the fired run</td></tr><tr><td><code>name</code></td><td>Short human label, and the fired run&#39;s title</td></tr><tr><td><code>schedule</code></td><td>The cron expression, evaluated in local time</td></tr><tr><td><code>brief</code></td><td>The objective handed to <code>startRun()</code> on every fire</td></tr><tr><td><code>project</code></td><td>Optional registry project the fired run is scoped to</td></tr><tr><td><code>enabled</code></td><td>The kill switch</td></tr><tr><td><code>nextFireAt</code></td><td>Next occurrence, ms epoch. Recomputed on boot, after every fire, and after every edit</td></tr><tr><td><code>lastFiredAt</code></td><td>When the last successful fire happened</td></tr><tr><td><code>lastRunId</code></td><td>The run created by the most recent fire — the only link between a cron and its runs</td></tr><tr><td><code>lastSkippedAt</code> / <code>lastSkipReason</code></td><td>Why the most recent attempt did not produce a run</td></tr></tbody></table><p>There is no field pointing from a run back to the cron that started it. The relationship is one-directional: the cron remembers its <code>lastRunId</code>.</p><h2 id="schedule-syntax" tabindex="-1">Schedule syntax <a class="header-anchor" href="#schedule-syntax" aria-label="Permalink to &quot;Schedule syntax&quot;">​</a></h2><p>Schedules are parsed by <a href="https://www.npmjs.com/package/croner" target="_blank" rel="noreferrer">croner</a>, which accepts the standard five-field expression plus an optional leading seconds field and an optional trailing year field:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────── (optional) second   0-59</span></span>
<span class="line"><span>│ ┌─────────── minute              0-59</span></span>
<span class="line"><span>│ │ ┌───────── hour                0-23</span></span>
<span class="line"><span>│ │ │ ┌─────── day of month        1-31</span></span>
<span class="line"><span>│ │ │ │ ┌───── month               1-12 or JAN-DEC</span></span>
<span class="line"><span>│ │ │ │ │ ┌─── day of week         0-7 or SUN-SAT</span></span>
<span class="line"><span>│ │ │ │ │ │</span></span>
<span class="line"><span>* * * * * *</span></span></code></pre></div><p>Beyond the usual <code>*</code>, <code>,</code>, <code>-</code>, and <code>/</code>, croner supports <code>L</code> (last), <code>W</code> (nearest weekday), and <code>#</code> (nth weekday of the month).</p><table tabindex="0"><thead><tr><th>Expression</th><th>Fires</th></tr></thead><tbody><tr><td><code>0 9 * * 1-5</code></td><td>Weekdays at 09:00</td></tr><tr><td><code>*/30 * * * *</code></td><td>Every 30 minutes</td></tr><tr><td><code>0 7 1 * *</code></td><td>07:00 on the first of each month</td></tr><tr><td><code>0 18 * * FRI</code></td><td>Fridays at 18:00</td></tr></tbody></table><p>Sub-minute precision is not useful in practice. The scheduler sweeps on a timer whose default is 60 seconds, so an expression finer than that fires at most once per sweep.</p><p>A schedule is validated before it is stored, by asking croner for the next occurrence. An expression that fails to parse, or that parses but never fires, is rejected with the parser&#39;s own message rather than being silently accepted.</p><h2 id="timezone" tabindex="-1">Timezone <a class="header-anchor" href="#timezone" aria-label="Permalink to &quot;Timezone&quot;">​</a></h2><p>Croner is constructed with no timezone option, so every schedule is evaluated in the <strong>host process&#39;s local time</strong> — whatever <code>TZ</code> or system zone the server runs under. There is no per-cron timezone field on the record, in the Mongo schema, or in the create/update path.</p><p>In a multi-tenant deployment this means all orgs&#39; crons fire on the server&#39;s clock, not on each member&#39;s. If your members are not in the server&#39;s zone, write the expression in the server&#39;s zone.</p><h2 id="what-a-fire-does" tabindex="-1">What a fire does <a class="header-anchor" href="#what-a-fire-does" aria-label="Permalink to &quot;What a fire does&quot;">​</a></h2><p><code>fireCron()</code> wraps everything in the cron&#39;s own tenant scope — its <code>orgId</code>, acting as its <code>createdBy</code> user, with <code>via: &#39;cron&#39;</code> — and then calls the run engine directly:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> startRun</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  brief: c.brief,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  project: c.project,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  title: c.name,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  playbookId: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">playbookForBrief</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(c.brief),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>That last argument matters. A cron is by definition repeated work, so if a playbook was already proven and saved for this exact brief, the fire replays it rather than paying to re-derive a plan — and lands on the same shape of result every time instead of a fresh interpretation.</p><p>Nothing else is passed. Effort mode, provider profile, model, and execution mode all fall back to the Settings defaults in force at the moment of the fire, and are then stamped onto the run so a later Settings change cannot reshape work already in flight.</p><p><code>startRun()</code> applies its normal gates regardless of who called it: the credit hard stop, org status, the member&#39;s monthly budget, and the member&#39;s and org&#39;s live-run concurrency ceilings. A cron fire that trips one of these throws, and is recorded as a skip.</p><p>On success the cron stamps <code>lastFiredAt</code> and <code>lastRunId</code>, clears any previous skip fields, and is persisted.</p><h2 id="overlap" tabindex="-1">Overlap <a class="header-anchor" href="#overlap" aria-label="Permalink to &quot;Overlap&quot;">​</a></h2><p>Overlapping fires are <strong>skipped, not queued</strong>. Before firing, the scheduler checks whether the run from the previous fire is still live:</p><p>A schedule&#39;s previous run counts as still live when its status is <code>active</code> <strong>or</strong><code>awaiting_input</code>. If it is, this fire is dropped.</p><p>Note that <code>awaiting_input</code> counts as live. A run blocked on a question or an approval gate holds the slot — a daily cron whose run is sitting on an unanswered approval will keep skipping until you answer it. That is the intended behaviour: double-booking the same project with two runs working the same brief is worse than a missed day.</p><p>A skipped fire records <code>lastSkippedAt</code> and a <code>lastSkipReason</code> naming the run that blocked it, then rolls <code>nextFireAt</code> forward to the next occurrence.</p><p>The same check runs inside <code>fireCron()</code> itself, so the manual &quot;run now&quot; path refuses too, with a <code>409</code>.</p><p>There is no distributed lock or leader election. The scheduler is an in-process timer, so two orchestrator processes sharing one database would each sweep the same crons.</p><h2 id="failure-behaviour" tabindex="-1">Failure behaviour <a class="header-anchor" href="#failure-behaviour" aria-label="Permalink to &quot;Failure behaviour&quot;">​</a></h2><p>A cron is never auto-disabled. There is no failure counter, no retry, and no <code>lastError</code> field on the record.</p><p>If <code>startRun()</code> throws, the error message is written to <code>lastSkipReason</code> with <code>lastSkippedAt</code>, <code>nextFireAt</code> rolls forward, and the cron tries again at its next occurrence. A genuine failure and an overlap skip therefore surface through the same two fields — read the reason text to tell them apart.</p><p>One edge worth knowing: if a schedule somehow becomes unparseable, <code>nextFireAt</code> is cleared, the sweep&#39;s self-heal branch tries to recompute it every tick, and the cron stays enabled but never fires. Nothing surfaces as an error. Validation on create and update is what normally prevents this.</p><h2 id="enable-disable-and-edit" tabindex="-1">Enable, disable, and edit <a class="header-anchor" href="#enable-disable-and-edit" aria-label="Permalink to &quot;Enable, disable, and edit&quot;">​</a></h2><p><code>enabled: false</code> is a pause, not a delete. A disabled cron keeps its record and its history but has its <code>nextFireAt</code> cleared, and the sweep skips it entirely.</p><p>Any edit re-anchors the schedule from now. Change the brief, the name, the project, or the schedule itself and <code>nextFireAt</code> is recomputed from the current moment — so an edit at 14:00 to a <code>0 9 * * *</code> cron sets the next fire to tomorrow morning, never to a moment that has already passed. Re-enabling a paused cron does the same.</p><p>Deleting a cron is permanent and stops future fires. Runs it already started are unaffected and continue normally.</p><h2 id="the-sweep" tabindex="-1">The sweep <a class="header-anchor" href="#the-sweep" aria-label="Permalink to &quot;The sweep&quot;">​</a></h2><p><code>startCronScheduler()</code> is called once at startup, after the org stores are hydrated and after the run engine is configured — the scheduler starts runs, so the engine must be ready before it ticks.</p><p>The boot pass recomputes every enabled cron&#39;s <code>nextFireAt</code> from <em>now</em>. This is the <strong>missed-fires-are-skipped</strong> policy: occurrences that passed while the server was off or asleep never fire, and nothing catches up on restart.</p><p>Then a self-rescheduling <code>setTimeout</code> — not a <code>setInterval</code> — sweeps every loaded org, each inside its own tenant scope. Using a fresh timeout each pass means a change to <code>cronTickSeconds</code> in Settings applies from the next sweep with no restart. The timer is unrefed, so it never keeps the process alive on its own.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>cronTickSeconds</code></td><td><code>60</code></td><td>Sweep interval. Minimum <code>5</code>; values below that are rejected</td></tr></tbody></table><p>Each sweep, per org: bail immediately if no cron is enabled; then for each enabled cron, self-heal a missing <code>nextFireAt</code>, skip anything not yet due, and otherwise either skip for overlap or fire. See <a href="/docs/reference/settings">Settings</a>.</p><h2 id="where-state-lives" tabindex="-1">Where state lives <a class="header-anchor" href="#where-state-lives" aria-label="Permalink to &quot;Where state lives&quot;">​</a></h2><p>MongoDB is authoritative. Each cron is one document keyed by its own id, written with a full replacement rather than a patch, so cleared optional fields such as <code>lastSkipReason</code> actually disappear instead of lingering.</p><p>In memory, each org has a <code>CronStore</code> holding the working copy — the same working-copy plus write-through shape the run store uses. <code>memory/crons.json</code> exists only as legacy migration input; in cloud mode the store refuses to persist at all while Mongo is unavailable, rather than silently writing to a file nobody reads.</p><p>Every durable change is broadcast to that org&#39;s dashboards over the WebSocket bridge as <code>cron_update</code>, and a deletion as <code>cron_removed</code>. Crons have no streaming — there is nothing to stream, since the work itself happens inside the run.</p><h2 id="managing-crons" tabindex="-1">Managing crons <a class="header-anchor" href="#managing-crons" aria-label="Permalink to &quot;Managing crons&quot;">​</a></h2><p>Over HTTP:</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/crons</code></td><td>List, most recently updated first</td></tr><tr><td><code>POST</code></td><td><code>/api/crons</code></td><td>Create <code>{ name, schedule, brief, project?, enabled? }</code></td></tr><tr><td><code>PATCH</code></td><td><code>/api/crons/:id</code></td><td>Update any of the same fields</td></tr><tr><td><code>DELETE</code></td><td><code>/api/crons/:id</code></td><td>Permanently delete</td></tr><tr><td><code>POST</code></td><td><code>/api/crons/:id/run</code></td><td>Fire now — still refuses with <code>409</code> if the previous run is live</td></tr></tbody></table><p>Or in chat, through PRIME&#39;s tools — <code>list_crons</code>, <code>create_cron</code>, <code>update_cron</code>, and <code>delete_cron</code>, all gated on the <code>crons.manage</code> permission, with deletion asking you to confirm first:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>create_cron(</span></span>
<span class="line"><span>  name: &quot;Morning triage&quot;,</span></span>
<span class="line"><span>  schedule: &quot;0 9 * * 1-5&quot;,</span></span>
<span class="line"><span>  brief: &quot;Review overnight alerts and open a summary.&quot;,</span></span>
<span class="line"><span>  project: &quot;billing-api&quot;</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>Both paths run through the same validation module, so a schedule PRIME accepts is exactly one the API would accept.</p><h2 id="crons-versus-reflexes" tabindex="-1">Crons versus reflexes <a class="header-anchor" href="#crons-versus-reflexes" aria-label="Permalink to &quot;Crons versus reflexes&quot;">​</a></h2><p>The two automations are deliberately symmetrical: a reflex is a cron whose trigger is an event instead of a clock. They share the convention of acting as their creator and of starting runs, but they are separate subsystems.</p><table tabindex="0"><thead><tr><th></th><th>Cron</th><th>Reflex</th></tr></thead><tbody><tr><td>Trigger</td><td>A schedule</td><td>A matched event on the bus</td></tr><tr><td>Action</td><td>Always: start a run</td><td>One of several action kinds</td></tr><tr><td>Controls</td><td><code>enabled</code></td><td><code>enabled</code>, <code>cooldownSec</code>, <code>dedupKey</code>, <code>maxFires</code>, <code>requireApproval</code></td></tr><tr><td>Auto-disable</td><td>Never</td><td>After <code>maxFires</code></td></tr><tr><td>Repeat suppression</td><td>Overlap skip</td><td>Cooldown and dedup key</td></tr><tr><td>History</td><td>Last fire and last skip only</td><td>A full append-only fire log</td></tr></tbody></table><p>A cron does not emit an event, and <code>cron</code> is not an event source — so a reflex cannot be made to listen for a cron firing. If you need that chain, have the cron&#39;s run finish and match on the resulting <code>run.finished</code> event instead.</p><p>See also: <a href="/docs/concepts/runs">Runs</a> · <a href="/docs/concepts/reflexes-and-events">Reflexes &amp; Events</a> · <a href="/docs/guides/building-a-reflex">Building a Reflex</a> · <a href="/docs/reference/reflex-rules">Reflex Rules</a></p>`,60)])])}const u=s(i,[["render",r]]);export{k as __pageData,u as default};
